SELECT o.*, od.id AS od_id, od.name AS od_name, od.order_id AS od_order_id, od.dish_id AS od_dish_id, od.setmeal_id AS od_setmeal_id, od.dish_flavor AS od_dish_flavor, od.number AS od_number, od.amount AS od_amount, od.image AS od_image FROM orders o LEFT JOIN order_detail od ON o.id = od.order_id WHERE o.user_id = #{userId}
AND o.status = #{status}
ORDER BY o.order_time DESC

SELECT o.*, od.id AS od_id, od.name AS od_name, od.order_id AS od_order_id, od.dish_id AS od_dish_id, od.setmeal_id AS od_setmeal_id, od.dish_flavor AS od_dish_flavor, od.number AS od_number, od.amount AS od_amount, od.image AS od_image FROM orders o LEFT JOIN order_detail od ON o.id = od.order_id
AND o.number = #{number}
AND o.phone = #{phone}
AND o.status = #{status}
AND o.order_time >= #{beginTime}
AND o.order_time <= #{endTime}
