UPDATE orders
SET status        = #{cancelledStatus},
    cancel_reason = #{cancelReason},
    cancel_time   = #{cancelTime}
WHERE status = #{status}
  AND order_time < #{timeoutThreshold}

UPDATE orders
SET status        = #{completedStatus},
    delivery_time = #{deliveryTime}
WHERE status = #{status}

mapper.select:
SELECT DATE(o.order_time)          AS order_date,
       COALESCE(SUM(o.amount), 0) AS turnover
FROM orders o
WHERE o.status = #{status}
  AND o.order_time >= #{begin}
  AND o.order_time < #{end}
  AND EXISTS (SELECT 1 FROM employee e WHERE e.id = #{employeeId})
GROUP BY DATE(o.order_time)
ORDER BY order_date

